diff --git a/packages/svelte/tests/runtime-runes/samples/object-has-own-reactive/_config.js b/packages/svelte/tests/runtime-runes/samples/object-has-own-reactive/_config.js
new file mode 100644
index 000000000000..17344b343d86
--- /dev/null
+++ b/packages/svelte/tests/runtime-runes/samples/object-has-own-reactive/_config.js
@@ -0,0 +1,24 @@
+import { test } from '../../test';
+import { tick } from 'svelte';
+
+export default test({
+	html: `<button>add y</button><button>delete y</button><p>false</p>`,
+
+	async test({ assert, target }) {
+		const [add, remove] = target.querySelectorAll('button');
+
+		add.click();
+		await tick();
+		assert.htmlEqual(
+			target.innerHTML,
+			`<button>add y</button><button>delete y</button><p>true</p>`
+		);
+
+		remove.click();
+		await tick();
+		assert.htmlEqual(
+			target.innerHTML,
+			`<button>add y</button><button>delete y</button><p>false</p>`
+		);
+	}
+});
diff --git a/packages/svelte/tests/runtime-runes/samples/object-has-own-reactive/main.svelte b/packages/svelte/tests/runtime-runes/samples/object-has-own-reactive/main.svelte
new file mode 100644
index 000000000000..bd0773ae8300
--- /dev/null
+++ b/packages/svelte/tests/runtime-runes/samples/object-has-own-reactive/main.svelte
@@ -0,0 +1,7 @@
+<script>
+	let state = $state({});
+</script>
+
+<button onclick={() => (state.y = true)}>add y</button>
+<button onclick={() => delete state.y}>delete y</button>
+<p>{Object.hasOwn(state, 'y')}</p>

